// Packs the Stockfish worker script and its WASM into one plain script (stockfish-bundle.js)
// so the page can start Stockfish even when opened straight from disk (file://), where
// browsers refuse to load workers or fetch .wasm files. Run: node stockfish/make-bundle.js
const fs = require('fs');
const path = require('path');
const dir = __dirname;
const js = fs.readFileSync(path.join(dir, 'stockfish-19-lite-single.js'), 'utf8');
const wasm = fs.readFileSync(path.join(dir, 'stockfish-19-lite-single.wasm')).toString('base64');
const out = '/* Generated by make-bundle.js from stockfish-19-lite-single.js/.wasm (Stockfish.js 19, GPLv3, see Copying.txt). */\n' +
  `window.STOCKFISH_BUNDLE = { js: ${JSON.stringify(js)}, wasm: "${wasm}" };\n`;
fs.writeFileSync(path.join(dir, 'stockfish-bundle.js'), out);
console.log('wrote stockfish-bundle.js', out.length, 'bytes');
